const D = { energy:.55, density:.5, hue:280, speed:1, scale:1, x:.5, y:.5, jag:.5, halo:.6, style:'plasma_globe', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u=Math.min(width,height);
if(!S.spr){ const R=72; const s=createGraphics(R*2,R*2); s.pixelDensity(1); s.noStroke();
  for(let r=R;r>0;r--){ const a=Math.pow(1-r/R,2.0)*255; s.fill(255,255,255,a*0.85); s.ellipse(R,R,r*2,r*2); }
  S.spr=s; }
if(S.seedUsed!==P.seed){ S.seedUsed=P.seed;
  const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453; return s-Math.floor(s);};
  S.hoff=fr(1);
  // each filament: target angle, target radius, phase offsets, branch flag
  S.fil=[]; for(let k=0;k<10;k++) S.fil.push([fr(k*5+2)*6.28, 0.5+fr(k*5+3)*0.5, fr(k*5+4)*6.28, fr(k*5+5), fr(k*5+6)]);
}
const sd=P.seed|0;
function nz(x){ return Math.sin(x*1.7)+0.5*Math.sin(x*3.9+1.2)+0.25*Math.sin(x*7.1+2.3); }

const t=K.t*(0.4+P.speed*0.6);
const style=P.style;
const cx=P.x*width, cy=P.y*height;
// core + tip color by style
const core = style==='tesla'?[205,60]:style==='arc_weld'?[210,20]:style==='faraday'?[150,70]:[290,70];
const tip  = style==='tesla'?[195,40]:style==='arc_weld'?[35,80]:style==='faraday'?[170,60]:[315,65];

// --- central plasma halo + faint ionized haze (broad area element) ---
push(); blendMode(ADD); imageMode(CENTER); noStroke();
const breath=0.6+0.4*Math.sin(t*0.7)+0.2*Math.sin(t*1.9+1.0)+A.mid*0.4;   // gentle, non-strobe
const hstr=(0.3+P.halo*0.9)*(0.5+P.energy*0.8)*breath;
tint((P.hue)%360, core[1]*0.6, 100, Math.min(100, 12*hstr)); image(S.spr, cx, cy, u*1.5*P.scale, u*1.5*P.scale);
tint((P.hue)%360, core[1], 100, Math.min(100, 30*hstr)); image(S.spr, cx, cy, u*0.5*P.scale, u*0.5*P.scale);
// faint full-field ionization so the whole frame reads charged
blendMode(ADD); noStroke(); fill((P.hue)%360, core[1]*0.4, 100, 2.5+2.0*hstr*0.4); rect(0,0,width,height);
imageMode(CORNER); blendMode(BLEND); pop();

// --- crawling filaments (slow re-route, never a strike) ---
const nf=2+Math.round(P.density*7);
const reach=u*(0.28+P.scale*0.22);
const jag=(0.4+P.jag*1.2);
push(); blendMode(ADD);
for(let k=0;k<nf;k++){ const fl=S.fil[k];
  // endpoint slowly wanders (crawl) on incommensurate rates
  const ang=fl[0] + 0.5*Math.sin(t*0.23*(0.6+fl[3]) + fl[2]) + 0.3*Math.sin(t*0.41 + k);
  const rad=reach*fl[1]*(0.8+0.2*Math.sin(t*0.3+fl[4]*6.28));
  const ex=cx+Math.cos(ang)*rad, ey=cy+Math.sin(ang)*rad;
  const seg=14;
  const bri=(0.5+0.5*Math.sin(t*0.9+fl[3]*6.28))*(0.5+P.energy*0.9);
  // build path: interpolate center->endpoint with slowly-evolving perpendicular jitter
  const pts=[];
  for(let s2=0;s2<=seg;s2++){ const f2=s2/seg;
    const bx=cx+(ex-cx)*f2, by=cy+(ey-cy)*f2;
    const perp=(-(ey-cy)*(1/(rad+1)))*1, ppx=-(ey-cy)/(rad+0.001), ppy=(ex-cx)/(rad+0.001);
    const wig=jag*u*0.06*Math.sin(f2*9 + t*1.1 + fl[2]*3)*(f2*(1-f2)*4) + jag*u*0.03*nz(f2*6 + t*0.7 + k);
    pts.push([bx+ppx*wig, by+ppy*wig]);
  }
  // glow layers: wide soft -> thin bright core
  for(let pass=0;pass<3;pass++){
    const w=[u*0.02, u*0.008, u*0.0025][pass];
    const hue=pass<1?tip[0]:core[0], sat=pass<1?tip[1]:core[1];
    const a=[10,26,70][pass]*bri;
    stroke(hue, sat, 100, Math.min(95,a)); strokeWeight(w); noFill();
    beginShape();
    for(let s2=0;s2<pts.length;s2++) vertex(pts[s2][0], pts[s2][1]);
    endShape();
  }
  // occasional branch (also slow)
  if(fl[4]<(0.2+P.density*0.35)){
    const bi=Math.floor(seg*(0.4+0.4*fl[3]));
    const bp=pts[bi]; const bang=Math.atan2(bp[1]-cy,bp[0]-cx)+ (fl[3]-0.5)*1.4;
    const blen=rad*0.4*(0.5+P.jag);
    const ex2=bp[0]+Math.cos(bang)*blen, ey2=bp[1]+Math.sin(bang)*blen;
    stroke(core[0],core[1],100, Math.min(90,40*bri)); strokeWeight(u*0.004);
    line(bp[0],bp[1],ex2 + jag*u*0.03*nz(t*0.9+k), ey2 + jag*u*0.03*nz(t*0.7+k*2));
  }
}
blendMode(BLEND); pop();
